    const i = t.indexOf(a);
    if (i < 0) return '';
    const from = i + a.length;
    const ends = b.map((x) => t.indexOf(x, from)).filter((x) => x >= 0);
    return t.slice(from, ends.length ? Math.min(...ends) : undefined).trim();
  };
