const r = $('Разбить на отзывы').item.json;
const ai = parseAi($json.text);
if (!ai.reply) throw new Error(`Модель вернула пустой ответ на отзыв ${r.id}`);
return { json: { ...r, ...ai, card: buildCard(r, ai, 1) } };
